import java.lang.reflect.*;
import java.util.*;

public class Main {
    interface OrderService {
        String pay(String id);
        String outerDirect(String id);
        String outerViaProxy(OrderService self, String id);
    }

    static class OrderServiceImpl implements OrderService {
        private final List<String> log;
        OrderServiceImpl(List<String> log) { this.log = log; }
        public String pay(String id) {
            log.add("target pay " + id);
            return "paid:" + id;
        }
        public String outerDirect(String id) {
            log.add("target outerDirect " + id);
            return "outer->" + this.pay(id);
        }
        public String outerViaProxy(OrderService self, String id) {
            log.add("target outerViaProxy " + id);
            return "outer->" + self.pay(id);
        }
    }

    interface Advice { Object invoke(Chain chain) throws Throwable; }
    interface TargetCall { Object invoke() throws Throwable; }

    static class Chain {
        final String methodName;
        final List<Advice> advices;
        final TargetCall targetCall;
        int index;
        Chain(String methodName, List<Advice> advices, TargetCall targetCall) {
            this.methodName = methodName;
            this.advices = advices;
            this.targetCall = targetCall;
        }
        Object proceed() throws Throwable {
            if (index < advices.size()) {
                return advices.get(index++).invoke(this);
            }
            return targetCall.invoke();
        }
    }

    static OrderService proxyFor(OrderService target, List<String> log) {
        List<Advice> advices = List.of(
            chain -> {
                log.add("tx begin " + chain.methodName);
                try {
                    Object result = chain.proceed();
                    log.add("tx commit " + chain.methodName);
                    return result;
                } catch (Throwable ex) {
                    log.add("tx rollback " + chain.methodName);
                    throw ex;
                }
            },
            chain -> {
                log.add("metric before " + chain.methodName);
                Object result = chain.proceed();
                log.add("metric after " + chain.methodName);
                return result;
            }
        );
        InvocationHandler handler = (proxy, method, args) -> {
            if (method.getDeclaringClass() == Object.class) {
                return method.invoke(target, args);
            }
            Chain chain = new Chain(method.getName(), advices, () -> {
                try {
                    return method.invoke(target, args);
                } catch (InvocationTargetException ex) {
                    throw ex.getCause();
                }
            });
            return chain.proceed();
        };
        return (OrderService) Proxy.newProxyInstance(
            OrderService.class.getClassLoader(),
            new Class<?>[] { OrderService.class },
            handler
        );
    }

    static long payAdviceCount(List<String> log) {
        return log.stream().filter(s -> s.equals("tx begin pay")).count();
    }

    static void printCase(String title, String result, List<String> log) {
        System.out.println("[" + title + "] " + result);
        log.forEach(System.out::println);
    }

    public static void main(String[] args) {
        List<String> log = new ArrayList<>();
        OrderServiceImpl target = new OrderServiceImpl(log);
        OrderService proxy = proxyFor(target, log);

        String directProxy = proxy.pay("A");
        assert payAdviceCount(log) == 1;
        printCase("proxy.pay", directProxy, log);
        log.clear();

        String selfCall = proxy.outerDirect("B");
        long selfPayAdvice = payAdviceCount(log);
        assert selfPayAdvice == 0;
        printCase("this.pay bypass", selfCall + ", payAdvice=" + selfPayAdvice, log);
        log.clear();

        String proxyCall = proxy.outerViaProxy(proxy, "C");
        long proxyPayAdvice = payAdviceCount(log);
        assert proxyPayAdvice == 1;
        printCase("self proxy call", proxyCall + ", payAdvice=" + proxyPayAdvice, log);
    }
}
